CREATE TABLE RUNWAY (RECD_TYPE varchar(1) ,CUST_AREA varchar(3) ,SECT_CODE varchar(1) ,ARPT_IDENT varchar(4) ,ARPT_ICAO_CODE varchar(2) ,SUBS_CODE varchar(1) ,RUNWAY_IDENT varchar(5) ,CONT_NR varchar(1) ,RUNWAY_LENGTH real,RUNWAY_MAG_BEARING bearing ,RUNWAY_LAT real,RUNWAY_LON real,RUNWAY_GRADIENT real,ELLIPSOID_HEIGHT real,LANDING_THLD_ELEV real,DISPLACED_THLD_DISTANCE real,THLD_CROSSING_HEIGHT real,RUNWAY_WIDTH real,TCH_VALUE_IND varchar(1) ,LOCALIZER_MLS_GLS_REF_PATH_IDENT varchar(4) ,LOCALIZER_MLS_GLS_CATEGORY_CLASS varchar(1) ,STOPWAY varchar(4) ,SECOND_LOCALIZER_MLS_GLS_REF_PATH_IDENT varchar(4) ,SECOND_LOCALIZER_MLS_GLS_CATEGORY_CLASS varchar(1) ,RUNWAY_DESCR varchar(22) ,FILE_RECD_NR real,CYCLE real);
